-- Stores the frozen A3Q_C2 GPT Native packet in unit_metadata and hands it to GPT Native as an operational event
-- (HANDOFF_DEEP_CONTEXT). Data only: no action spec, checkpoint status or assertion changes. C2 stays PENDING.
-- The event carries a pointer to the packet, its hashes and the instructions text; it declares no acceptance.
-- Tier: OWNER_APPROVED_GPT_NATIVE_IN_CHAT_EQUIVALENT (not provider-attested).
BEGIN;
DO $a3q_c2_prep$
DECLARE
 v_plan constant text := 'PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1';
 v_unit constant text := 'A3Q';
 v_cp constant text := 'A3Q_C2';
 v_wi constant bigint := 1113;
 v_exec constant text := 'ANALYSIS_QUAL_C2_GPT_HANDOFF_V1|A3Q_C2';
 v_packet_sha constant text := '31f91c187a95d6d09e279c5fa78ae66e70a911e3f4ef85bd6c25435ddf0b97ea';
 v_packet jsonb := $pkt${"checkpoint":"C2","deterministic_checks":{"expected_values":{"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2":{"input_sha256":"a1974eae630ef1eea450e6bd95248a73da785257de73b06e13fb727190e76987","packet_sha256":"1cbe8daa96f35a3a37b194659c690fcbd9437407c465d32987c956a5eef10b4a","request_sha256":"a136daa7486437dc62b8757993b5213b3b6b2575bb32cb08e2a5217c84df3071"},"supabase://public.lf_eventos/20843":{"created_by_execution_id":"ANALYSIS_QUAL_C2_GPT_HANDOFF_V1|A1Q_C2","evento_tipo":"HANDOFF_DEEP_CONTEXT","payload_packet_sha256":"1cbe8daa96f35a3a37b194659c690fcbd9437407c465d32987c956a5eef10b4a"}},"fields":{"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2":["packet_sha256","request_sha256","input_sha256"],"supabase://public.lf_eventos/20843":["evento_tipo","created_by_execution_id","payload_packet_sha256"]},"forbidden_solution_patterns":["\\bredis\\b","\\bkafka\\b","\\bpostgres\\w*","\\breact\\b","\\bsql\\b","\\bapi\\b","\\bendpoint\\b","\\btrigger\\b","\\bmigraci\\w+","\\bmicroservic\\w+","\\brpc\\b","\\bedge function\\b","\\btabla\\b","\\bbase de datos\\b","\\bcomponente\\b"],"request_ref_equals":"REQ-LF-A1Q-C2-PILOT-0001","supplied_sources":["supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2","supabase://public.lf_eventos/20843"],"verdicts":["BLOCKED","NEED_MORE_EVIDENCE","REQUIRES_DECISION","SUFFICIENT"]},"evidence_tier":"OWNER_APPROVED_GPT_NATIVE_IN_CHAT_EQUIVALENT","input":{"input_literal":"{\n  \"a2_stage_output\": {\n    \"classification\": {\n      \"authority_state\": \"UNKNOWN\",\n      \"change_type\": \"Cambio funcional orientado a claridad de información económica previa a la aceptación de una oferta. No se determina si corresponde modificar una capacidad existente o introducir una nueva.\",\n      \"depth\": \"L3\",\n      \"implementation_state\": \"UNKNOWN\",\n      \"target_granularity\": \"Capacidad funcional de comunicación y comprensión del ahorro en la negociación de deuda, antes de aceptar una oferta. Pantalla, canal, segmento y alcance exactos no identificados.\"\n    },\n    \"depth_reason\": \"L3 por materialidad HIGH: la solicitud afecta la comprensión de importes económicos antes de aceptar una oferta de negociación de deuda. La definición del ahorro y su base de comparación son materialmente desconocidas, al igual que el significado de la cuota, el límite entre oferta y aceptación, el alcance del piloto y el criterio de comprensión. Existen cinco ambigüedades explícitamente clasificadas MATERIAL y OPEN. No se observa una contradicción factual explícita, pero tampoco existe evidencia suficiente para determinar alcance entre procesos, autoridad vigente, implementación existente, reversibilidad o actualidad de las fuentes. La cantidad 0 de especialistas refleja únicamente que ninguno está identificado expresamente en el contexto, no que se haya demostrado que no son necesarios. La regla de precedencia exige L3 por materialidad HIGH, independientemente de las demás señales. No se infiere una solución técnica.\",\n    \"evidence_refs\": [\n      \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2.input.input_literal\",\n      \"supabase://public.lf_eventos/20843\",\n      \"ambiguity:SAVINGS_MEANING_AND_BASIS\",\n      \"ambiguity:OFFER_AND_ACCEPTANCE_BOUNDARY\",\n      \"ambiguity:CLIENT_CHANNEL_AND_SCOPE\",\n      \"ambiguity:INSTALLMENT_MEANING\",\n      \"ambiguity:COMPREHENSION_CRITERION\"\n    ],\n    \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n    \"schema_version\": \"A2_CLASSIFICATION_OUTPUT_V1\",\n    \"signal_sources\": [\n      {\n        \"signal\": \"materiality_level\",\n        \"source_ref\": \"ambiguity:SAVINGS_MEANING_AND_BASIS\"\n      },\n      {\n        \"signal\": \"scope_bounded\",\n        \"source_ref\": \"ambiguity:CLIENT_CHANNEL_AND_SCOPE\"\n      },\n      {\n        \"signal\": \"authority_state\",\n        \"source_ref\": \"NO_SOURCE_SUPPLIED\"\n      },\n      {\n        \"signal\": \"reversibility_state\",\n        \"source_ref\": \"NO_SOURCE_SUPPLIED\"\n      },\n      {\n        \"signal\": \"currentness_decision\",\n        \"source_ref\": \"NO_SOURCE_SUPPLIED\"\n      },\n      {\n        \"signal\": \"material_contradiction\",\n        \"source_ref\": \"supabase://public.lf_eventos/20843\"\n      },\n      {\n        \"signal\": \"known_cross_scope_impact\",\n        \"source_ref\": \"ambiguity:CLIENT_CHANNEL_AND_SCOPE\"\n      },\n      {\n        \"signal\": \"unresolved_material_signal_count\",\n        \"source_ref\": \"supabase://public.lf_eventos/20843\"\n      },\n      {\n        \"signal\": \"required_specialist_count\",\n        \"source_ref\": \"NO_SOURCE_SUPPLIED\"\n      }\n    ],\n    \"signals\": {\n      \"authority_state\": \"UNKNOWN\",\n      \"currentness_decision\": \"UNKNOWN_FAIL_CLOSED\",\n      \"known_cross_scope_impact\": \"UNKNOWN\",\n      \"material_contradiction\": false,\n      \"materiality_level\": \"HIGH\",\n      \"required_specialist_count\": 0,\n      \"reversibility_state\": \"UNKNOWN\",\n      \"scope_bounded\": \"UNKNOWN\",\n      \"unresolved_material_signal_count\": 5\n    }\n  },\n  \"supplied_sources\": [\n    {\n      \"fields_to_report\": [\n        \"packet_sha256\",\n        \"request_sha256\",\n        \"input_sha256\"\n      ],\n      \"source_ref\": \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\"\n    },\n    {\n      \"fields_to_report\": [\n        \"evento_tipo\",\n        \"created_by_execution_id\",\n        \"payload_packet_sha256\"\n      ],\n      \"source_ref\": \"supabase://public.lf_eventos/20843\"\n    }\n  ]\n}","input_origin":"A2Q_C2 GPT Native RAW (raw_output_sha256 381a76bccf5e26696460897a68a87b1960ad6882c065b0c171953334d54ebcde) + two supplied sources","input_sha256":"e35bee22e553786d96110a89bc559a19577e066e904b627d80cd45458f9fdf28","request_ref":"REQ-LF-A1Q-C2-PILOT-0001"},"limits":{"checkpoint_transition":false,"db_write":false,"independent_assurance_admitted":false,"provider_attested":false,"real_execution_receipt":false,"transcript_is_provider_evidence":false},"output_contract":{"required_keys":["schema_version","request_ref","evidence_items","source_refs","currentness_refs","target_granularity","authority_state","implementation_state","target_resolution","authority_binding_refs","as_is_baseline_or_new_implementation_evidence","unresolved_material_gaps","sufficiency_verdict","stop_reason"],"schema":"A3_TARGETED_EVIDENCE_OUTPUT_V1","validator":"analysis_qualification_a3q_c2_gpt_native_packet_v1.py::semantic_checks"},"owner_approval_doc":"docs/programming-agent/ANALYSIS_C2C3_GPT_NATIVE_APPROVED_EQUIVALENT_V1.md","packet_sha256":"31f91c187a95d6d09e279c5fa78ae66e70a911e3f4ef85bd6c25435ddf0b97ea","producer_mode":"GPT_NATIVE","profile_source":{"ref":"profiles/programming_analysis_lf/SKILL.md","sha256":"91a7b47c3d84f1d5aea48f3fd475134d9c56c718461d1b649c4a89d53980508f"},"prompt_for_gpt":"Este mensaje es independiente: ignora cualquier otro paquete o salida anterior de este chat. Eres el productor de la etapa A3 (evidencia dirigida) del perfil de análisis. Recibes la salida de la etapa A2 y DOS fuentes exactas (abajo). Debes LEER cada fuente con tu conector de Supabase de solo lectura y reportar el valor EXACTO de cada campo pedido. Regla de investigación mínima: no leas nada más que esas dos fuentes. Si no puedes leer una fuente, marca read_status='NOT_READ', deja observed_fields vacío y NO inventes valores. Estas fuentes describen el pipeline de análisis, no el objetivo de la solicitud: no declares estado de autoridad o de implementación del objetivo sin evidencia (usa UNKNOWN), no inventes línea base AS-IS ni delta, y el veredicto no puede ser SUFFICIENT mientras falte evidencia material del objetivo. No infieras solución técnica. Devuelve SOLO un objeto JSON, sin texto adicional, con exactamente estas claves: schema_version, request_ref, evidence_items, source_refs, currentness_refs, target_granularity, authority_state, implementation_state, target_resolution, authority_binding_refs, as_is_baseline_or_new_implementation_evidence, unresolved_material_gaps, sufficiency_verdict, stop_reason. schema_version='A3_TARGETED_EVIDENCE_OUTPUT_V1'. request_ref='REQ-LF-A1Q-C2-PILOT-0001'. evidence_items=lista con UN elemento por fuente suministrada: {source_ref, read_status (READ|NOT_READ), observed_fields (objeto con exactamente los campos pedidos para esa fuente), currentness_basis (READ_IN_THIS_RUN|UNVERIFIED)}. source_refs=lista de las fuentes leídas. currentness_refs=lista de fuentes con currentness_basis=READ_IN_THIS_RUN. target_granularity=el target_granularity de la clasificación A2 (texto). authority_state e implementation_state (EXISTING|NEW|UNKNOWN). target_resolution={authority_state, implementation_state, resolved (booleano), reason (texto)}. authority_binding_refs=lista de referencias de autoridad del objetivo (vacía si no hay). as_is_baseline_or_new_implementation_evidence={kind (NONE_SUPPLIED|AS_IS_BASELINE|NEW_IMPLEMENTATION_EVIDENCE), refs (lista)}. unresolved_material_gaps=lista de {gap_code, statement} (al menos una si falta evidencia del objetivo). sufficiency_verdict (SUFFICIENT|NEED_MORE_EVIDENCE|REQUIRES_DECISION|BLOCKED). stop_reason=texto no vacío.\n\nENTRADA (JSON):\n{\n  \"a2_stage_output\": {\n    \"classification\": {\n      \"authority_state\": \"UNKNOWN\",\n      \"change_type\": \"Cambio funcional orientado a claridad de información económica previa a la aceptación de una oferta. No se determina si corresponde modificar una capacidad existente o introducir una nueva.\",\n      \"depth\": \"L3\",\n      \"implementation_state\": \"UNKNOWN\",\n      \"target_granularity\": \"Capacidad funcional de comunicación y comprensión del ahorro en la negociación de deuda, antes de aceptar una oferta. Pantalla, canal, segmento y alcance exactos no identificados.\"\n    },\n    \"depth_reason\": \"L3 por materialidad HIGH: la solicitud afecta la comprensión de importes económicos antes de aceptar una oferta de negociación de deuda. La definición del ahorro y su base de comparación son materialmente desconocidas, al igual que el significado de la cuota, el límite entre oferta y aceptación, el alcance del piloto y el criterio de comprensión. Existen cinco ambigüedades explícitamente clasificadas MATERIAL y OPEN. No se observa una contradicción factual explícita, pero tampoco existe evidencia suficiente para determinar alcance entre procesos, autoridad vigente, implementación existente, reversibilidad o actualidad de las fuentes. La cantidad 0 de especialistas refleja únicamente que ninguno está identificado expresamente en el contexto, no que se haya demostrado que no son necesarios. La regla de precedencia exige L3 por materialidad HIGH, independientemente de las demás señales. No se infiere una solución técnica.\",\n    \"evidence_refs\": [\n      \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2.input.input_literal\",\n      \"supabase://public.lf_eventos/20843\",\n      \"ambiguity:SAVINGS_MEANING_AND_BASIS\",\n      \"ambiguity:OFFER_AND_ACCEPTANCE_BOUNDARY\",\n      \"ambiguity:CLIENT_CHANNEL_AND_SCOPE\",\n      \"ambiguity:INSTALLMENT_MEANING\",\n      \"ambiguity:COMPREHENSION_CRITERION\"\n    ],\n    \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n    \"schema_version\": \"A2_CLASSIFICATION_OUTPUT_V1\",\n    \"signal_sources\": [\n      {\n        \"signal\": \"materiality_level\",\n        \"source_ref\": \"ambiguity:SAVINGS_MEANING_AND_BASIS\"\n      },\n      {\n        \"signal\": \"scope_bounded\",\n        \"source_ref\": \"ambiguity:CLIENT_CHANNEL_AND_SCOPE\"\n      },\n      {\n        \"signal\": \"authority_state\",\n        \"source_ref\": \"NO_SOURCE_SUPPLIED\"\n      },\n      {\n        \"signal\": \"reversibility_state\",\n        \"source_ref\": \"NO_SOURCE_SUPPLIED\"\n      },\n      {\n        \"signal\": \"currentness_decision\",\n        \"source_ref\": \"NO_SOURCE_SUPPLIED\"\n      },\n      {\n        \"signal\": \"material_contradiction\",\n        \"source_ref\": \"supabase://public.lf_eventos/20843\"\n      },\n      {\n        \"signal\": \"known_cross_scope_impact\",\n        \"source_ref\": \"ambiguity:CLIENT_CHANNEL_AND_SCOPE\"\n      },\n      {\n        \"signal\": \"unresolved_material_signal_count\",\n        \"source_ref\": \"supabase://public.lf_eventos/20843\"\n      },\n      {\n        \"signal\": \"required_specialist_count\",\n        \"source_ref\": \"NO_SOURCE_SUPPLIED\"\n      }\n    ],\n    \"signals\": {\n      \"authority_state\": \"UNKNOWN\",\n      \"currentness_decision\": \"UNKNOWN_FAIL_CLOSED\",\n      \"known_cross_scope_impact\": \"UNKNOWN\",\n      \"material_contradiction\": false,\n      \"materiality_level\": \"HIGH\",\n      \"required_specialist_count\": 0,\n      \"reversibility_state\": \"UNKNOWN\",\n      \"scope_bounded\": \"UNKNOWN\",\n      \"unresolved_material_signal_count\": 5\n    }\n  },\n  \"supplied_sources\": [\n    {\n      \"fields_to_report\": [\n        \"packet_sha256\",\n        \"request_sha256\",\n        \"input_sha256\"\n      ],\n      \"source_ref\": \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\"\n    },\n    {\n      \"fields_to_report\": [\n        \"evento_tipo\",\n        \"created_by_execution_id\",\n        \"payload_packet_sha256\"\n      ],\n      \"source_ref\": \"supabase://public.lf_eventos/20843\"\n    }\n  ]\n}","request_sha256":"aa729c4210c35ed03a6dbed15822a4eaa15930a5eb905657110532aae8a56a93","run_id":"A3Q_C2-GPTN-PILOT-0001","schema":"ANALYSIS_GPT_NATIVE_PACKET_V1","stage_output_selector":"A3","subject_ref":"PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1/A3Q/A3Q_C2","unit":"A3"}$pkt$;
 v_m jsonb; v_before_specs jsonb; v_before_cps text; v_after_cps text; v_stored jsonb; v_id bigint; v_p jsonb;
BEGIN
 IF v_packet->>'packet_sha256' IS DISTINCT FROM v_packet_sha OR v_packet->>'subject_ref' <> v_plan||'/'||v_unit||'/'||v_cp
  THEN RAISE EXCEPTION 'A3Q_C2_PACKET_IDENTITY'; END IF;
 IF encode(sha256(convert_to(v_packet#>>'{input,input_literal}','UTF8')),'hex') <> v_packet#>>'{input,input_sha256}'
  THEN RAISE EXCEPTION 'A3Q_C2_INPUT_SHA_MISMATCH'; END IF;
 IF (v_packet#>>'{limits,provider_attested}')::boolean IS NOT FALSE OR (v_packet#>>'{limits,real_execution_receipt}')::boolean IS NOT FALSE
  THEN RAISE EXCEPTION 'A3Q_C2_LIMITS_NOT_FALSE'; END IF;
 IF (SELECT status FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi AND checkpoint_code=v_cp) IS DISTINCT FROM 'PENDING'
  THEN RAISE EXCEPTION 'A3Q_C2_NOT_PENDING'; END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_before_cps
  FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi FOR UPDATE;
 IF v_m IS NULL THEN RAISE EXCEPTION 'A3Q_UNIT_NOT_FOUND'; END IF;
 IF v_m#>'{gpt_native_packets_v1,A3Q_C2}' IS NOT NULL AND v_m#>>'{gpt_native_packets_v1,A3Q_C2,packet_sha256}' <> v_packet_sha
  THEN RAISE EXCEPTION 'A3Q_C2_PACKET_DIFFERENT_ALREADY_STORED'; END IF;
 v_before_specs := v_m->'action_specs_v1';
 UPDATE programacion.engineering_plan_units
    SET unit_metadata = v_m || jsonb_build_object('gpt_native_packets_v1',
        COALESCE(v_m->'gpt_native_packets_v1','{}'::jsonb) || jsonb_build_object('A3Q_C2',v_packet))
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 v_stored := v_m#>'{gpt_native_packets_v1,A3Q_C2}';
 IF v_stored IS DISTINCT FROM v_packet THEN RAISE EXCEPTION 'A3Q_C2_PACKET_READBACK_MISMATCH'; END IF;
 IF v_m->'action_specs_v1' IS DISTINCT FROM v_before_specs THEN RAISE EXCEPTION 'A3Q_C2_SPECS_CHANGED'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.lf_eventos WHERE evento_tipo='HANDOFF_DEEP_CONTEXT' AND created_by_execution_id=v_exec) THEN
  INSERT INTO public.lf_eventos(evento_tipo,entidad_tipo,entidad_codigo,descripcion,severidad,origen,created_by_execution_id,payload)
  VALUES('HANDOFF_DEEP_CONTEXT','PROGRAM_PLAN',v_plan||'.A3Q_C2.GPT_NATIVE_HANDOFF',
   'Frozen A3Q_C2 packet handed to GPT Native for a producer run; no acceptance declared.','INFO','DERIVE_FROM_EXECUTION_ID',v_exec,
   jsonb_build_object(
    'evidence_schema_version','operational-event/v2','execution_id',v_exec,
    'producer','ANALYSIS_QUAL_C2_GPT_HANDOFF_V1',
    'purpose','Hand the frozen A3Q_C2 packet to GPT Native so it can produce the stage output in its own chat.',
    'occurred_at',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"+00:00"'),
    'acceptance_declared',false,
    'subject_ref',v_packet->>'subject_ref','checkpoint',v_cp,'work_item_id',v_wi,
    'packet_location','supabase://programacion.engineering_plan_units/'||v_unit||'#unit_metadata.gpt_native_packets_v1.'||v_cp,
    'packet_sha256',v_packet_sha,'request_sha256',v_packet->>'request_sha256',
    'input_sha256',v_packet#>>'{input,input_sha256}','producer_mode','GPT_NATIVE',
    'evidence_tier',v_packet->>'evidence_tier','provider_attested',false,
    'instructions_for_gpt',v_packet->>'prompt_for_gpt',
    'return_instructions','Reply in the same chat with ONLY the JSON object, unedited. Keep the chat link; the verifier needs the RAW JSON, the chat link and the transcript SHA-256. Do not claim provider attestation.',
    'limits_note','Owner-approved GPT Native in-chat equivalent. Not a provider receipt and not an independent review. The checkpoint stays pending until a captured output is verified.'))
  RETURNING id INTO v_id;
  SELECT payload INTO v_p FROM public.lf_eventos WHERE id=v_id;
  IF v_p->>'packet_sha256' IS DISTINCT FROM v_packet_sha OR v_p->>'instructions_for_gpt' IS DISTINCT FROM v_packet->>'prompt_for_gpt'
   THEN RAISE EXCEPTION 'A3Q_C2_HANDOFF_READBACK_MISMATCH'; END IF;
 END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_after_cps
  FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 IF v_after_cps IS DISTINCT FROM v_before_cps THEN RAISE EXCEPTION 'A3Q_C2_CHECKPOINTS_CHANGED'; END IF;
END
$a3q_c2_prep$;
COMMIT;
